window.ATLAS={theme:'为虚构竞技世界设计原创硬质头部穿戴装备；借鉴《Marathon》的 Graphic Realism 和跨领域工业产品的几何构成，以非常规轮廓、清晰体块、少量有效细节建立陌生但可信的产品家族，可直接探索配色、材质、图形与皮肤。',pillars:[['P1','剪影先行','先有形体身份，再有局部精度'],['P2','图形化产品构成','几何比例、负空间与壳体分层'],['P3','受控陌生感与系列性','在同一系统中，探索不同形态']],branches:[{id:'01',en:'VISOR CORE',name:'前脸主体化',idea:'将视觉重心推向前脸，在闭合的悬念与打开的揭示之间建立形态身份。',limits:['闭合状态不得提前暴露内部光学布局。','不得移动自然眼位来解决鼻梁遮挡。','不得用装饰刻线代替前脸真实体量。'],checks:[['前脸体量','严格侧视测量 P/L，目标 18%–22%。'],['开合对应','三块部件轮廓对应，冠部固定，部件不消失。'],['光学与眼位','光学单元占据规定眼位，鼻部完整，遮挡合理。']],cases:[]},{id:'02',en:'SIDE POD',name:'侧部体块主导 · 目镜式',idea:'以宽幅目镜与紧凑耳罩组织侧部结构，让护颏与后脑共同形成识别轮廓。',limits:['目镜不得退化为狭窄眼缝。','耳罩不得膨胀为外扩长箱。','新架构不能仅替换尾壳，配色也不固定复用。'],checks:[['目镜与耳罩','宽幅滑雪镜比例，方正耳罩贴近耳位。'],['护颏与尾部','护颏向前上方兜住下巴，尾部具有清楚负空间。'],['材质与一致性','自然皮肤，符号化涂鸦，三视图几何与图形对应。']],cases:[]},{id:'03',en:'PANEL SHELL',name:'折板错层',idea:'通过大板块的折转、高差与搭接，让结构秩序直接成为外轮廓。',limits:['本方向无展开形态，面罩保持全闭合。','错层不能退化为表面刻线。','护梁不得脱离耳罩，面罩符号不使用文字。'],checks:[['三段错层','后／中／前约 4∶1∶2，三部分高差清楚。'],['材质与连接','哑光顶板、反光面罩；护梁从耳罩内部衍生。'],['配色与符号','上下分色、两主色约 1∶1，抽象符号跨视图对应。']],cases:[]}]};
ATLAS.branches.forEach(b=>{b.cases=Array.from({length:3},(_,i)=>({id:b.id+'-'+String(i+1).padStart(2,'0'),title:['形态探索','结构迭代','配色与材质'][i],description:['建立主要体块与轮廓识别。','检验连接、比例与三视图一致性。','探索色彩、表面与图形关系。'][i],image:null,thinking:'待补充：本案例想解决的问题、关键设计选择，以及从参考到原创方案的转化。',references:Array.from({length:5},(_,j)=>({title:'参考 '+(j+1),image:null,source:'出处待补充',url:'',learn:'待说明具体学习的部位与设计关系。',application:'待标注在本方案中的应用位置。'})),prompt:'待填入本案例实际使用的提示词。\n\n建议保留：设计目标、造型约束、参考图角色、固定机位、输出格式与本轮修改项。',logs:[]}))});
